/**
 * Stackra file contract:
 * Purpose: `MANIFEST_NOTICE`, the `$comment` gen writes at the top of a committed `stackra.manifest.json`.
 * Boundary: a constant string.
 * Runtime: isomorphic
 * Governing contract: ADR 0294 (decisions 10 and 22); ADR 0305 (rule 36).
 */

/** The manifest's `$comment`. */
export const MANIFEST_NOTICE =
  "GENERATED by stackra gen, COMMITTED at the member root (ADR 0294 decision 10). The member contract: other members " +
  "generate clients, event classes and UI from it, and openapi.json beside it is its projection. It locks every " +
  "identity, derived or written; a changed identity fails `stackra gen --check` unless the class carries @Renamed(old).";
